__NUXT_JSONP__("/th/price", (function(a,b,c,d,e,f,g,h,i,j,k,l,m){return {data:[{details:{slug:c,pageTitle:"ราคา | Mentor Language Institute",pageDescription:"หากท่านจัดหาที่อยู่อาศัยเอง ท่านไม่จำเป็นต้องจ่าย ② ค่าที่พัก",title:"ราคา",image:"\u002Fimages\u002Fprices\u002Fprice\u002Fget-a-quote.jpg",button:{lists:[{link:["\u003Ca class=\"btn btn-primary\" href=\"\u002Fth\u002Fprice-auto\"\u003Eการคำนวณราคา\u003C\u002Fa\u003E"]}]},steps:{title:"① ค่าเรียน＋② ค่าหอพัก＋③ ค่าใช้จ่ายอื่นๆ",subtitle:["หากท่านจัดหาที่อยู่อาศัยเอง ท่านไม่จำเป็นต้องจ่าย ② ค่าที่พัก\u003Cbr\u003E *ท่านสามารถ คลิก  \u003Ca href=\"\u002Fth\u002Fprice-auto\u002F\"\u003Eการคำนวณราคา\u003C\u002Fa\u003E  เพื่อคำนวณราคาเบื้องต้น"],lists:[{title:"① ค่าเรียน",subtitle:["ราคาสามารถเปลี่ยนแปลงได้ ขึ้นอยู่กับหลักสูตรและระยะเวลาการเข้าพักของท่าน\u003Cbr \u002F\u003E ท่านเรียนที่ MLI นานเท่าไร ก็ยิ่งมีส่วนลดมากขึ้นเท่านั้น"],image:"\u002Fimages\u002Fprices\u002Fprice\u002FPRICE_CHART_WEB_JAN06.jpg",link:["\u003Cb\u003Eคำถามและคำตอบ\u003C\u002Fb\u003E","\u003Cb\u003Eข้อ1: ฉันสามารถชำระค่าธรรมเนียมด้วยบัตรเครดิตได้ไหม? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003Eคำตอบ1:\u003C\u002Fb\u003E ได้ค่ะ\u002Fครับ คุณสามารถชำระด้วยบัตรเครดิตได้ แต่จะมีการคิดค่าบริการ 4% เพิ่มเติม","\u003Cb\u003Eข้อ2: ฉันสามารถใช้วิธีการชำระเงินแบบใดในการชำระเงินให้ MLI ได้บ้าง?\u003C\u002Fb\u003E \u003Cbr \u002F\u003E\u003Cb\u003Eคำตอบ2:\u003C\u002Fb\u003E เรารับวิธีการชำระเงินดังต่อไปนี้: \u003Cbr\u003E • การโอนเงินผ่านธนาคาร \u003Cbr\u003E • การโอนเงินระหว่างประเทศ \u003Cbr\u003E • เงินสด \u003Cbr\u003E • เช็คส่วนบุคคล \u003Cbr\u003E • บัตรเครดิต \u003Cbr\u003E • บัตรเดบิต \u003Cbr\u003E • Zelle","หากคุณต้องการหลีกเลี่ยงค่าธรรมเนียมบริการ 4% สำหรับการชำระเงินด้วยบัตรเครดิต\u002Fเดบิต คุณสามารถเลือกวิธีอื่นต่อไปนี้ได้: \u003Cbr\u003E\u003Cb\u003Eการโอนเงินผ่านธนาคาร, การโอนเงินระหว่างประเทศ (มีค่าธรรมเนียมธนาคาร 35 ดอลลาร์), เงินสด, เช็คส่วนบุคคล หรือ Zelle.\u003C\u002Fb\u003E","\u003Cb\u003Eข้อ3: ฉันสามารถชำระค่าเรียนหลังจากเริ่มโปรแกรมได้ไหม? \u003C\u002Fb\u003E\u003Cbr \u002F\u003E\u003Cb\u003Eคำตอบ3:\u003C\u002Fb\u003E ไม่ได้ ต้องชำระค่าเรียนเต็มจำนวนก่อนหรือภายในวันแรกของโปรแกรม"],category:[{title:"บริการเสริม",table:{tableMaxCol:d,title_optional:"การเปลี่ยนสถานะ (หากคุณมีวีซ่า B1\u002FB2 หรือ J1 และปัจจุบันอยู่ในสหรัฐอเมริกา) หรือการคืนสถานะ",tbody:[["\u003Cb\u003Eคำอธิบายค่าธรรมเนียม\u003C\u002Fb\u003E","\u003Cb\u003Eประเภทผู้สมัคร\u003C\u002Fb\u003E","\u003Cb\u003Eค่าธรรมเนียม\u003C\u002Fb\u003E","\u003Cb\u003Eจำนวนผู้สมัคร\u003C\u002Fb\u003E"],["ค่าบริการ $1,885 รวมค่าธรรมเนียมการกรอก ($370) และค่าธรรมเนียมการส่งไปรษณีย์ \u003Cbr\u003E *เมื่อได้รับอนุมัติ จะมีการใช้ $600 เป็นเครดิตค่าเล่าเรียนสำหรับนักเรียน (มูลค่าที่ไม่ใช่เงินสด)","วีซ่านักเรียน F1","$1,885","1"],["ค่าบริการ $365 สำหรับผู้อยู่ในอุปการะแต่ละคน","วีซ่าขึ้นอยู่กับ F2","$365",b]]}}]},{title:"② ค่าที่พัก",subtitle:["เราสามารถจัดหาบ้านพักและหอพักสำหรับนักเรียนได้ \u003Cbr \u002F\u003E เรามีบ้านพักแนะนำสำหรับผู้ที่ต้องการสัมผัสกับวัฒนธรรมอเมริกัน \u003Cbr \u002F\u003E หอพักเหมาะสำหรับผู้ที่ต้องการสร้างเครือข่ายและเพื่อน"],category:[{title:"ราคาบ้านพัก",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003E หากอายุน้อยกว่า 18 ปี ค่าเช่าจะสูงกว่าราคาของผู้ที่มีอายุมากกว่า 18 ปีประมาณ 10%",thead:[b,e,"Shared***"],tbody:[[f,a,a],[g,"$436","$384"],[h,"$872","$768"],[i,"$1,308","$1,152"],[j,"$1,744","$1,536"],[k,"$3,160","$2,904"],[l,"$4,740","$4,356"]]}},{title:"ราคาค่าที่พัก",table:{tableMaxCol:d,title:"Placement Fee* : $200\u003Cbr \u002F\u003E หากอายุน้อยกว่า 18 ปี ค่าเช่าจะสูงกว่าราคาของผู้ที่มีอายุมากกว่า 18 ปีประมาณ 10%",thead:[b,e,"Shared (2 people)","Quad (4 people)"],tbody:[[f,a,a,a],[g,"$570","$430","$315"],[h,"$1,140","$860","$630"],[i,"$1,710","$1,290","$945"],[j,"$2,280","$1,720","$1,260"],[k,"$4,320","$3,080","$2,320"],[l,"$6,480","$4,620","$3,480"]]},description:["*ค่าธรรมเนียมการจองจะไม่สามารถคืนเงินได้\u003Cbr \u002F\u003E**ท่านจะได้รับค่ามัดจำคืนหลังจากย้ายออก\u003Cbr \u002F\u003E***หากท่านต้องการเข้าพักแบบแบ่งห้อง \u003Cspan class=\"rmarker\"\u003Eท่านต้องอยู่กับผู้อื่นด้วย\u003C\u002Fspan\u003E","※ห้องพักของท่านจะได้รับการดูแลจากบริษัท U.S. Support Service หรือตัวแทนอื่นๆ","\u003Ca href=\"\u002Fth\u002Fstay\u002F\"\u003E\u003Ci class='bi bi-arrow-right'\u003E\u003C\u002Fi\u003E   ข้อมูลเพิ่มเติมเกี่ยวกับหอพัก\u003C\u002Fa\u003E"]}]},{title:"③ ค่าใช้จ่ายอื่นๆ",subtitle:["นอกเหนือจากค่าธรรมเนียมด้านบน ยังมีค่าธรรมเนียมอื่นๆ"],lists:["ค่าธรรมเนียมการสมัครเรียน $150","ค่าจัดส่งเอกสาร I-20 $120","ค่าดำเนินการ SEVIS $350 (จ่ายให้กับ SEVP)","ค่าหนังสือเรียน $150-240"],description:["**ไม่สามารถคืนได้\u003Cbr \u002F\u003E**ท่านมีวีซ่านักเรียน"]}]},examples:{title:"ตัวอย่าง",subtitle:["นี่คือตัวอย่างการชำระค่าเรียน ระหว่าง 4 สัปดาห์และ 48 สัปดาห์"],lists:[{title:"1 เดือน\u002F4 สัปดาห์",items:[m,"ค่าเรียน $1,220","ค่าที่พัก $1,630（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003Eรวม $3,000\u003C\u002Fspan\u003E"]},{title:"1 ปี (48 สัปดาห์)",items:[m,"รวม $10,032","ค่าที่พัก $13,810（Dormitory : Quad Rent + Placement Fee + Airport Pickup- oneway)","\u003Cspan class='total'\u003Eรวม $23,992\u003C\u002Fspan\u003E"]}]},other_info:["หากท่านมีคำถามเกี่ยวกับค่าธรรมเนียม โปรดติดต่อเรา"],dir:"\u002Fprice",path:"\u002Fprice\u002Fth",extension:".json",createdAt:"2026-10-22T16:31:30.195Z",updatedAt:"2026-03-24T13:34:16.714Z"},lang:c}],fetch:{},mutations:void 0}}("$300","","th",4,"Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks","ค่าธรรมเนียม $150")));